<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUseRef;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseUserVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseConditionsVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseAcceptDateVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseIpAddressVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseUserAgentVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseVersionVO;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\UserAcceptedTermsOfUseAttributes;
use PHPUnit\Framework\TestCase;

final class UserAcceptedTermsOfUseAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserAcceptedTermsOfUseAttributes();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrCurrent(UserAcceptedTermsOfUseUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrCurrent(UserAcceptedTermsOfUseUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrCurrent(UserAcceptedTermsOfUseUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrCurrent(UserAcceptedTermsOfUseUserVO::from($userOtherValue))->value());
        $conditionsOneValue = new TenantTermsOfUseRef('one');
        $conditionsOtherValue = new TenantTermsOfUseRef('other');
        $copy = $value->conditions($conditionsOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantTermsOfUseRef('one'), $value->getConditions());
        $this->assertNotEquals(new TenantTermsOfUseRef('other'), $value->getConditions());
        $this->assertEquals(new TenantTermsOfUseRef('one'), $value->getConditionsOrCurrent(UserAcceptedTermsOfUseConditionsVO::from($conditionsOtherValue))->value());
        $this->assertNotEquals(new TenantTermsOfUseRef('other'), $value->getConditionsOrCurrent(UserAcceptedTermsOfUseConditionsVO::from($conditionsOtherValue))->value());
        $value->unsetConditions();
        $this->assertEquals(new TenantTermsOfUseRef('other'), $value->getConditionsOrCurrent(UserAcceptedTermsOfUseConditionsVO::from($conditionsOtherValue))->value());
        $this->assertNotEquals(new TenantTermsOfUseRef('one'), $value->getConditionsOrCurrent(UserAcceptedTermsOfUseConditionsVO::from($conditionsOtherValue))->value());
        $acceptDateOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $acceptDateOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->acceptDate($acceptDateOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getAcceptDate());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getAcceptDate());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getAcceptDateOrCurrent(UserAcceptedTermsOfUseAcceptDateVO::from($acceptDateOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getAcceptDateOrCurrent(UserAcceptedTermsOfUseAcceptDateVO::from($acceptDateOtherValue))->value());
        $value->unsetAcceptDate();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getAcceptDateOrCurrent(UserAcceptedTermsOfUseAcceptDateVO::from($acceptDateOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getAcceptDateOrCurrent(UserAcceptedTermsOfUseAcceptDateVO::from($acceptDateOtherValue))->value());
        $ipAddressOneValue = 'one';
        $ipAddressOtherValue = 'other';
        $copy = $value->ipAddress($ipAddressOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getIpAddress());
        $this->assertNotEquals('other', $value->getIpAddress());
        $this->assertEquals('one', $value->getIpAddressOrCurrent(UserAcceptedTermsOfUseIpAddressVO::from($ipAddressOtherValue))->value());
        $this->assertNotEquals('other', $value->getIpAddressOrCurrent(UserAcceptedTermsOfUseIpAddressVO::from($ipAddressOtherValue))->value());
        $value->unsetIpAddress();
        $this->assertEquals('other', $value->getIpAddressOrCurrent(UserAcceptedTermsOfUseIpAddressVO::from($ipAddressOtherValue))->value());
        $this->assertNotEquals('one', $value->getIpAddressOrCurrent(UserAcceptedTermsOfUseIpAddressVO::from($ipAddressOtherValue))->value());
        $userAgentOneValue = 'one';
        $userAgentOtherValue = 'other';
        $copy = $value->userAgent($userAgentOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getUserAgent());
        $this->assertNotEquals('other', $value->getUserAgent());
        $this->assertEquals('one', $value->getUserAgentOrCurrent(UserAcceptedTermsOfUseUserAgentVO::from($userAgentOtherValue))->value());
        $this->assertNotEquals('other', $value->getUserAgentOrCurrent(UserAcceptedTermsOfUseUserAgentVO::from($userAgentOtherValue))->value());
        $value->unsetUserAgent();
        $this->assertEquals('other', $value->getUserAgentOrCurrent(UserAcceptedTermsOfUseUserAgentVO::from($userAgentOtherValue))->value());
        $this->assertNotEquals('one', $value->getUserAgentOrCurrent(UserAcceptedTermsOfUseUserAgentVO::from($userAgentOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(UserAcceptedTermsOfUseVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(UserAcceptedTermsOfUseVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(UserAcceptedTermsOfUseVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(UserAcceptedTermsOfUseVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
